alter table maintenance_work_orders add column if not exists cancel_reason text;
create or replace function maintenance_transition_work_order(p_organization_id uuid,p_work_order_id uuid,p_status text,p_root_cause text,p_resolution text,p_actor_id uuid,p_actor_email text,p_cancel_reason text default null)returns void language plpgsql security definer set search_path=public as $$declare old text;a uuid;allowed boolean:=false;begin select status,asset_id into old,a from maintenance_work_orders where id=p_work_order_id and organization_id=p_organization_id for update;if old is null then raise exception'Work order not found';end if;allowed:=case old when'open'then p_status in('open','in_progress','cancelled')when'in_progress'then p_status in('in_progress','waiting_parts','waiting_external','completed')when'waiting_parts'then p_status in('waiting_parts','in_progress','cancelled')when'waiting_external'then p_status in('waiting_external','in_progress','cancelled')else p_status=old end;if not allowed then raise exception'Invalid work order transition';end if;if p_status='completed'and nullif(trim(p_resolution),'')is null then raise exception'Resolution required';end if;if p_status='cancelled'and nullif(trim(p_cancel_reason),'')is null then raise exception'Cancellation reason required';end if;update maintenance_work_orders set status=p_status,root_cause=coalesce(nullif(trim(p_root_cause),''),root_cause),resolution=coalesce(nullif(trim(p_resolution),''),resolution),cancel_reason=coalesce(nullif(trim(p_cancel_reason),''),cancel_reason),started_at=case when p_status='in_progress'then coalesce(started_at,now())else started_at end,completed_at=case when p_status='completed'then now()else completed_at end,updated_at=now()where id=p_work_order_id;if old<>p_status then insert into maintenance_work_order_history(organization_id,work_order_id,from_status,to_status,changed_by,changed_by_email)values(p_organization_id,p_work_order_id,old,p_status,p_actor_id,p_actor_email);end if;if p_status='completed'then update maintenance_downtime_events set ended_at=now(),ended_by=p_actor_id where work_order_id=p_work_order_id and ended_at is null;update maintenance_assets set status='operational',updated_at=now()where id=a and not exists(select 1 from maintenance_downtime_events where asset_id=a and ended_at is null);elsif p_status='in_progress'then update maintenance_assets set status='maintenance',updated_at=now()where id=a and status<>'down';end if;end$$;
revoke all on function maintenance_transition_work_order(uuid,uuid,text,text,text,uuid,text,text)from public,anon,authenticated;grant execute on function maintenance_transition_work_order(uuid,uuid,text,text,text,uuid,text,text)to service_role;